// returned cursor exactly, and stops without another request when it is null.
func PaginateItems(fetch PageFetcher, limit int) (ItemsResponse, error) {
	if fetch == nil {
		return ItemsResponse{}, errors.New("nil page fetcher")
	}
	if limit < 1 {
		return ItemsResponse{}, errors.New("limit must be at least 1")
	}

	var cursor *string
	allItems := make([]Item, 0)
	for {
		page, err := fetch(ItemsRequest{Cursor: cursor, Limit: limit})
		if err != nil {
			return ItemsResponse{}, err
		}
		allItems = append(allItems, page.Items...)
		if page.NextCursor == nil {
			return ItemsResponse{Items: allItems, NextCursor: nil}, nil
		}
